static int run(void*c,const struct cl_target_plan*p,unsigned char*out,size_t cap,struct cl_target_result*r){unsigned i;(void)c;calls++;assert(p->opcode==opcode);assert(!strcmp(p->argv[0],"--host"));assert(!strcmp(p->argv[1],"npipe:////./pipe/dockerDesktopLinuxEngine"));assert(!strcmp(p->argv[2],"--config"));assert(!strcmp(p->argv[3],"D:\\held"));for(i=0;i<p->argc;i++)assert(!strstr(p->argv[i],"PRIVATE_DSN"));if(opcode==21){assert(p->argc==8&&cap==262144&&!p->input_bytes);assert(!strcmp(p->argv[4],"container")&&!strcmp(p->argv[5],"cp")&&!strcmp(p->argv[7],"-"));assert(strlen(p->argv[6])==64+strlen(":/data/.castlink-owner/12345678-1234-1234-1234-123456789abc/owner-invite.txt"));assert(!strcmp(p->argv[6]+64,":/data/.castlink-owner/12345678-1234-1234-1234-123456789abc/owner-invite.txt"));}else{assert(p->argc==12&&cap==2048);assert(!strcmp(p->argv[4],"exec")&&!strcmp(p->argv[5],"-i"));assert(!strcmp(p->argv[7],"/usr/bin/env")&&!strcmp(p->argv[8],"-i")&&!strcmp(p->argv[9],"/usr/local/bin/node")&&!strcmp(p->argv[10],"-e"));assert(p->input_bytes<=8192);assert(memmem(p->input,p->input_bytes,opcode==17?"\"family\":17":"\"family\":18",11));assert(memmem(p->input,p->input_bytes,"PRIVATE_DSN",11));assert(memmem(p->input,p->input_bytes,opcode==17?"\"phase\":\"initial\"":"\"serverName\":\"Own Server\"",opcode==17?17:25));}memcpy(out,"PRIVATE_ACK",11);r->bytes=11;r->reaped=!lost_reap;return 1;}
